package com.warehouse.twin.controller; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.warehouse.twin.common.Result; import com.warehouse.twin.entity.DisciplineRecord; import com.warehouse.twin.service.DisciplineRecordService; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/discipline-records") public class DisciplineController {private final DisciplineRecordService s;public DisciplineController(DisciplineRecordService s){this.s=s;}@GetMapping public Result<List<DisciplineRecord>> list(){return Result.ok(s.list(Wrappers.<DisciplineRecord>lambdaQuery().orderByDesc(DisciplineRecord::getReviewedAt)));}}
